function escapePythonString(value) {
  return value
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\t/g, '\\t');
}

function formatString(value) {
  return `'${escapePythonString(value)}'`;
}

export function formatPythonRepr(value) {
  if (value === null) {
    return 'None';
  }

  if (typeof value === 'string') {
    return formatString(value);
  }

  if (typeof value === 'number' || typeof value === 'bigint') {
    return String(value);
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => formatPythonRepr(item)).join(', ')}]`;
  }

  if (typeof value === 'object') {
    const entries = Object.entries(value).map(
      ([key, entryValue]) => `${formatString(key)}: ${formatPythonRepr(entryValue)}`,
    );
    return `{${entries.join(', ')}}`;
  }

  return formatString(String(value));
}

