import { sha256 } from './sha256.mjs';

const encoder = new TextEncoder();
const BLOCK_SIZE = 64;

function concatBytes(left, right) {
  const combined = new Uint8Array(left.length + right.length);
  combined.set(left, 0);
  combined.set(right, left.length);
  return combined;
}

function normalizeKey(secret) {
  let key = encoder.encode(secret);

  if (key.length > BLOCK_SIZE) {
    key = sha256(key);
  }

  if (key.length === BLOCK_SIZE) {
    return key;
  }

  const padded = new Uint8Array(BLOCK_SIZE);
  padded.set(key, 0);
  return padded;
}

export async function signHmacSha256(message, secret) {
  const key = normalizeKey(secret);
  const innerPad = new Uint8Array(BLOCK_SIZE);
  const outerPad = new Uint8Array(BLOCK_SIZE);

  for (let index = 0; index < BLOCK_SIZE; index += 1) {
    innerPad[index] = key[index] ^ 0x36;
    outerPad[index] = key[index] ^ 0x5c;
  }

  const messageBytes = encoder.encode(message);
  const innerHash = sha256(concatBytes(innerPad, messageBytes));
  return sha256(concatBytes(outerPad, innerHash));
}

export function timingSafeEqual(left, right) {
  if (left.length !== right.length) {
    return false;
  }

  let mismatch = 0;
  for (let index = 0; index < left.length; index += 1) {
    mismatch |= left[index] ^ right[index];
  }

  return mismatch === 0;
}

